theory('Introduction to Bits and Tricks', 'An int has 32 bits in two\'s-complement form. `&` keeps common set bits, `|` combines bits, `^` differs bits, `~` flips bits. `1 << i` addresses bit i for 0<=i<32. Java masks shift distances modulo 32 for int and modulo 64 for long, so validate indices. `>>` sign-extends; `>>>` fills with zero. `n & (n-1)` clears the lowest set bit; `n & -n` isolates it. int bit patterns may be negative; interpret unsigned values with `Integer.toUnsignedLong` when needed.')
bit_rows = [
 ('Check if the i-th bit is Set or Not','boolean','int n,int i','if(i<0||i>=32) throw new IllegalArgumentException(); return (n & (1<<i))!=0;','10,1','true','Use zero-based bit indices from the least-significant bit.','Mask only bit i; a nonzero intersection means it was set.','10 is binary 1010; bit 1 is one.'),
 ('Check if a Number is Odd or Not','boolean','int n','return (n&1)!=0;','-3','true','Check parity of a signed int.','The least significant bit determines odd/even parity, including negatives.','-3 has its least-significant bit set.'),
 ('Check if a Number is Power of 2 or Not','boolean','int n','return n>0 && (n&(n-1))==0;','16','true','Check whether a positive int is an integral power of two.','A positive power of two has exactly one set bit; clearing the lowest bit leaves zero.','10000 & 01111 = 00000.'),
 ('Count the Number of Set Bits','int','int n','int count=0; while(n!=0){ n &= n-1; count++; } return count;','-1','32','Count set bits in the complete 32-bit pattern.','Brian Kernighan clears one set bit per iteration.','-1 contains 32 one bits, so 32 iterations clear them.'),
 ('Set the Rightmost Unset Bit','int','int n','return n|(n+1);','10','11','Set the least-significant zero bit within a 32-bit pattern. All-ones stays unchanged.','n+1 carries through trailing ones; OR retains the original ones and sets the first zero.','1010 | 1011 = 1011.'),
 ('Minimum Bit Flips to Convert Number','int','int a,int b','return Integer.bitCount(a^b);','10,7','3','Count differing bits of two int patterns.','XOR is one exactly at differing positions; each needs one flip.','1010 XOR 0111 = 1101 has three set bits.'),
 ('Single Number - I','int','int[] a','int ans=0; for(int x:a) ans^=x; return ans;','new int[]{4,1,2,1,2}','4','Exactly one value occurs once and every other value twice.','Equal values cancel under XOR; order does not matter.','1^1 and 2^2 cancel, leaving 4.'),
 ('Single Number - II','int','int[] a','int once=0,twice=0; for(int x:a){ once=(once^x)&~twice; twice=(twice^x)&~once; } return once;','new int[]{2,2,3,2}','3','Exactly one value occurs once; every other value occurs three times.','Each bit has a finite-state count modulo three, represented by once/twice. Third occurrence clears the bit.','For 2 its bit cycles once -> twice -> neither; 3 remains once.')]
for title,typ,params,body,call,expected,contract,reason,trace in bit_rows:
    add(title,'    public static %s solve(%s){ %s }' % (typ,params,body), 'System.out.println(solve(%s));'%call,expected,
        contract,reason,'O(1) for one fixed-width int; O(n) for array XOR/state scans. O(1) space.',trace,
        'Java int overflow and shifts operate on fixed 32-bit patterns here. Never shift by an unchecked index of 32; it would shift by zero.')
add('Swap Two Numbers', '''    public static int[] solve(int a,int b){ a^=b; b^=a; a^=b; return new int[]{a,b}; }''','System.out.println(Arrays.toString(solve(3,7)));','[7, 3]',
    'Return swapped values; primitive caller variables cannot be mutated through method arguments.', 'XOR swaps local copies without an extra integer temporary; returning an array communicates both results.', 'O(1) time/space.', 'a=3^7; b=(3^7)^7=3; a=(3^7)^3=7.', 'Prefer a temporary variable in normal Java code for readability. XOR-swapping an array entry with itself would zero it.')
add('Single Number - III', '''    public static int[] solve(int[] a){ int xor=0; for(int x:a) xor^=x; int bit=xor&-xor,p=0,q=0; for(int x:a) if((x&bit)==0) p^=x; else q^=x; return p<q?new int[]{p,q}:new int[]{q,p}; }''','System.out.println(Arrays.toString(solve(new int[]{1,2,1,3,2,5})));','[3, 5]',
    'Exactly two distinct values occur once; every other value occurs twice. Return the two singletons sorted.', 'XOR all gives p^q, which is nonzero. A set bit differs between p and q; partition on that bit so repeated values cancel within each group.', 'O(n) time; O(1) space.', '3^5=6 (110); isolated bit 2 separates 3 from 5.', 'Signed MIN_VALUE can be an isolated bit; `(x&bit)!=0` remains correct. The input multiplicity contract is essential.')
add('Divide two numbers without multiplication and division', '''    public static int solve(int dividend,int divisor){
        if(divisor==0) throw new ArithmeticException("division by zero");
        if(dividend==Integer.MIN_VALUE && divisor==-1) return Integer.MAX_VALUE;
        long a=Math.abs((long)dividend),b=Math.abs((long)divisor),q=0;
        for(int bit=31;bit>=0;bit--) if((a>>bit)>=b){ a-=b<<bit; q|=1L<<bit; }
        return (int)((dividend<0)^(divisor<0)?-q:q);
    }''','System.out.println(solve(43,-8));','-5',
    'Compute quotient truncating toward zero without multiplication, division or remainder. Clamp the sole int-overflow quotient to MAX_VALUE.', 'Subtract the largest fitting power-of-two multiple of divisor at each bit from high to low; set that quotient bit. The remainder decreases while the reconstructed quotient accounts for every subtraction.', '32 iterations: O(1) for fixed-width inputs, O(1) space.', '43-32 leaves 11 and sets quotient bit 2; 11-8 leaves 3 and sets bit 0; quotient 5, sign makes -5.', 'Cast before abs to handle MIN_VALUE. b<<31 fits long for int magnitudes.')
add('Power Set Bit Manipulation', '''    public static List<List<Integer>> solve(int[] a){ if(a.length>20) throw new IllegalArgumentException("output is exponential; demo limit 20"); List<List<Integer>> out=new ArrayList<>(); for(int mask=0;mask<(1<<a.length);mask++){ List<Integer> row=new ArrayList<>(); for(int i=0;i<a.length;i++) if((mask&(1<<i))!=0) row.add(a[i]); out.add(row); } return out; }''','System.out.println(solve(new int[]{1,2}));','[[], [1], [2], [1, 2]]',
    'Enumerate positional subsets, including empty. Duplicate input values can create equal value lists.', 'A mask chooses each index independently. Every subset corresponds to exactly one n-bit mask.', 'O(n*2^n) time and output storage; O(n) working subset.', 'Masks 00,01,10,11 select {},{1},{2},{1,2}.', 'Java shifts mask counts; constrain n explicitly, and respect exponential memory. This teaching implementation limits n to 20.')
add('XOR of numbers in a given range', '''    private static int prefix(int n){ switch(n&3){ case 0:return n; case 1:return 1; case 2:return n+1; default:return 0; } }
    public static int solve(int l,int r){ if(l<0||r<l) throw new IllegalArgumentException(); return prefix(r)^(l==0?0:prefix(l-1)); }''','System.out.println(solve(3,9));','2',
    'XOR all nonnegative integers in the inclusive range [l,r].', 'Prefix XOR from 0 repeats a four-case cycle according to n mod 4. XOR two prefixes cancels all positions before l.', 'O(1) time/space.', 'prefix(9)=1 and prefix(2)=3; 1^3=2.', 'The formula is for nonnegative ordered bounds, not arbitrary signed intervals.')

add('Print all primes till N', sieve+'''\n    public static List<Integer> primes(int n){ boolean[] p=sieve(n); List<Integer> out=new ArrayList<>(); for(int i=2;i<p.length;i++) if(p[i]) out.add(i); return out; }''','System.out.println(primes(20));','[2, 3, 5, 7, 11, 13, 17, 19]',
    'Return primes <=n, n>=0.', 'Sieve composite multiples starting at p² for every unmarked p. Any composite has a prime factor <=sqrt(n), so it is eventually marked.', 'O(n log log n) time; O(n) sieve plus output space.', '2 marks evens above 2, 3 marks 9,15, then remaining values are prime.', 'n=0/1 returns empty. This uses an array of n+1 entries; huge ranges need segmentation.')
add('Prime factorisation of a Number', '''    public static List<Integer> solve(int n){ if(n<1) throw new IllegalArgumentException(); List<Integer> out=new ArrayList<>(); for(int p=2;p<=n/p;p++) while(n%p==0){ out.add(p); n/=p; } if(n>1) out.add(n); return out; }''','System.out.println(solve(360));','[2, 2, 2, 3, 3, 5]',
    'Return prime factors with multiplicity for positive n; 1 has an empty factorization.', 'Repeatedly divide by the smallest divisor. After exhausting smaller factors, the current divisor must be prime if it divides. Any leftover >1 after sqrt(current n) is prime.', 'O(sqrt(original n)) worst time; O(log n) output entries.', '360 -> divide 2 three times leaves 45 -> divide 3 twice leaves 5 -> append 5.', 'Loop bound uses the shrinking n. Reject zero, whose factorization is not finite.')
add('Count primes in range L to R', '''    public static int solve(int l,int r){
        if(l<0||r<l) throw new IllegalArgumentException(); if((long)r-l+1>10000000) throw new IllegalArgumentException("segment too large");
        int root=(int)Math.sqrt(r); while((long)(root+1)*(root+1)<=r) root++;
        boolean[] base=new boolean[root+1]; Arrays.fill(base,true); if(root>=0) base[0]=false; if(root>=1) base[1]=false;
        for(int p=2;p<=root/p;p++) if(base[p]) for(int j=p*p;j<=root;j+=p) base[j]=false;
        boolean[] composite=new boolean[r-l+1];
        for(int p=2;p<=root;p++) if(base[p]){ long start=Math.max((long)p*p,((long)l+p-1)/p*p); for(long x=start;x<=r;x+=p) composite[(int)(x-l)]=true; }
        int count=0; for(int i=0;i<composite.length;i++) if((long)l+i>=2 && !composite[i]) count++; return count;
    }''','System.out.println(solve(10,20));','4',
    'Count primes in inclusive [l,r] for nonnegative int endpoints. Segment length is limited to ten million to bound memory.', 'Sieve primes through sqrt(r), then mark only their multiples inside the segment, starting no earlier than p² so p is not marked composite.', 'O(sqrt(r) log log r + segmentLength*log log r + sqrt(r)) approximate sieve time; O(sqrt(r)+segmentLength) space.', '10..20 keeps 11,13,17,19.', 'Exclude 0 and 1 separately. Use long for first multiple and marking positions to avoid endpoint overflow.')
